contracts/Collection1155.sol.content:
// SPDX-License-Identifier: MIT
// Compatible with OpenZeppelin Contracts ^5.0.0
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "./IGmpReceiver.sol";
import "./IGateway.sol";

contract Collection1155 is ERC1155, Ownable, IGmpReceiver {
    using Strings for uint256;

    address public immutable _gateway;
    string public name;
    string public symbol;
    string public logoURI;
    uint256 private _nextTokenId;

    struct CrosschainMessage {
        uint256 tokenId;
        string tokenURI;
        address newHolder;
        uint256 amount;
    }

    mapping(uint256 => string) private _tokenURIs;
    mapping(uint256 => uint256) private _totalSupply;
    mapping(uint16 => address) private _crosschainContract;

    constructor(
        string memory _name,
        string memory _symbol,
        string memory _logoURI,
        address gateway
    ) ERC1155("") Ownable(msg.sender) {
        name = _name;
        symbol = _symbol;
        logoURI = _logoURI;
        _gateway = gateway;
    }

    // asuming the gateway already handles verification
    // we just need to mint on received
    function onGmpReceived(
        bytes32,
        uint128,
        bytes32,
        bytes calldata b
    ) external payable returns (bytes32) {
        require(msg.sender == _gateway, "unauthorized");
        CrosschainMessage memory message = abi.decode(b, (CrosschainMessage));
        mintByGateway(
            message.tokenId,
            message.newHolder,
            message.amount,
            message.tokenURI
        );
        return bytes32("");
    }

    function crosschainTransfer(
        uint256 _tokenId,
        string calldata _tokenURI,
        address _newHolder,
        uint256 _amount,
        uint16 _destinationNetwork
    ) public {
        require(
            _crosschainContract[_destinationNetwork] != address(0),
            "Crosschain: Unsupport Network"
        );
        require(
            balanceOf(msg.sender, _tokenId) >= _amount,
            "Crosschain: Insufficient amount owned by Sender"
        );
        burn(msg.sender, _tokenId, _amount);
        IGateway gateway = IGateway(_gateway);
        gateway.submitMessage(
            _crosschainContract[_destinationNetwork],
            _destinationNetwork,
            3000000,
            encodeCrosschainMessage(_tokenId, _tokenURI, _newHolder, _amount)
        );
    }

    function encodeCrosschainMessage(
        uint256 _tokenId,
        string memory _tokenURI,
        address _newHolder,
        uint256 _amount
    ) private pure returns (bytes memory) {
        CrosschainMessage memory message = CrosschainMessage(
            _tokenId,
            _tokenURI,
            _newHolder,
            _amount
        );
        return abi.encode(message);
    }

    function uri(uint256 tokenId) public view override returns (string memory) {
        return _tokenURIs[tokenId];
    }

    function mint(
        uint256 amount,
        string memory metadataURI,
        bytes memory data
    ) public onlyOwner {
        _mint(msg.sender, _nextTokenId, amount, data);
        _setTokenURI(_nextTokenId, metadataURI);
        _totalSupply[_nextTokenId] += amount;
        _nextTokenId++;
    }

    function mintByGateway(
        uint256 tokenId,
        address holder,
        uint256 amount,
        string memory metadataURI
    ) private {
        require(msg.sender == _gateway, "unauthorized");
        _mint(holder, tokenId, amount, "");
        _setTokenURI(tokenId, metadataURI);
        _totalSupply[tokenId] += amount;
    }

    function mintBatch(
        uint256[] memory amounts,
        string[] memory metadataURIs,
        bytes memory data
    ) public onlyOwner {
        require(
            amounts.length == metadataURIs.length,
            "Amounts and metadataURIs length mismatch"
        );

        uint256[] memory ids = new uint256[](amounts.length);
        for (uint256 i = 0; i < amounts.length; i++) {
            ids[i] = _nextTokenId;
            _setTokenURI(_nextTokenId, metadataURIs[i]);
            _totalSupply[_nextTokenId] += amounts[i];
            _nextTokenId++;
        }

        _mintBatch(msg.sender, ids, amounts, data);
    }

    function burn(address account, uint256 id, uint256 amount) public {
        require(
            balanceOf(account, id) >= amount,
            "Burn: caller insufficient amount"
        );
        _burn(account, id, amount);
        _totalSupply[id] -= amount;
    }

    function burnBatch(
        address account,
        uint256[] memory ids,
        uint256[] memory amounts
    ) public {
        require(ids.length == amounts.length);
        for (uint256 i = 0; i < ids.length; i++) {
            burn(account, ids[i], amounts[i]);
            _totalSupply[ids[i]] -= amounts[i];
        }
    }

    function _setTokenURI(uint256 tokenId, string memory metadataURI) internal {
        _tokenURIs[tokenId] = metadataURI;
    }

    function totalSupply(uint256 tokenId) public view returns (uint256) {
        return _totalSupply[tokenId];
    }
}

contracts/Collection721.sol.content:
// SPDX-License-Identifier: MIT
// Compatible with OpenZeppelin Contracts ^5.0.0
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Burnable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "./IGmpReceiver.sol";
import "./IGateway.sol";

contract Collection721 is
    ERC721,
    ERC721URIStorage,
    ERC721Burnable,
    Ownable,
    IGmpReceiver
{
    using Strings for uint256;

    address public immutable _gateway;
    uint256 private _nextTokenId;
    uint16 private _nextDropId;
    string public baseURI;
    string public logoURI;
    bool private _baseURISet;

    struct Drop {
        uint256 supply;
        uint256 minted;
        uint256 mintLimitPerWallet;
        uint256 startTime;
        uint256 endTime;
        uint256 price;
        bool hasWhiteListPhase;
        uint256 whiteListEndTime;
        uint256 whiteListPrice;
        mapping(address => bool) whiteListAddresses;
        mapping(address => uint256) mintedPerWallet;
    }

    struct DropReturn {
        uint256 supply;
        uint256 minted;
        uint256 mintLimitPerWallet;
        uint256 startTime;
        uint256 endTime;
        uint256 price;
        bool hasWhiteListPhase;
        uint256 whiteListEndTime;
        uint256 whiteListPrice;
    }

    struct CrosschainMessage {
        uint256 tokenId;
        address newHolder;
    }

    mapping(uint16 => Drop) private DropList;
    mapping(uint256 => address) private _burntBy;
    mapping(uint16 => address) private _crosschainContract;

    constructor(
        string memory _name,
        string memory _symbol,
        string memory _logoURI,
        address gateway
    ) ERC721(_name, _symbol) Ownable(msg.sender) {
        logoURI = _logoURI;
        _gateway = gateway;
    }

    modifier onlyDuringDrop() {
        Drop storage drop = DropList[_nextDropId];
        require(
            block.timestamp >= drop.startTime &&
                block.timestamp <= drop.endTime,
            "Drop not active"
        );
        _;
    }

    modifier onlyAfterDrop() {
        Drop storage drop = DropList[_nextDropId];
        require(
            drop.endTime != 0 && block.timestamp > drop.endTime,
            "Drop not end or no initial Drop"
        );
        _;
    }

    modifier canMint(uint256 amount) {
        Drop storage drop = DropList[_nextDropId];
        require(
            drop.mintedPerWallet[msg.sender] + amount <=
                drop.mintLimitPerWallet,
            "Mint limit per wallet exceeded"
        );
        require(drop.minted + amount <= drop.supply, "Exceeds drop supply");
        _;
    }

    modifier beforeUpload() {
        require(!_baseURISet, "Cannot proceed after upload");
        _;
    }

    function setCrosschainAddress(
        uint16 _network,
        address _contractAddress
    ) public onlyOwner {
        _crosschainContract[_network] = _contractAddress;
    }

    // asuming the gateway already handles verification
    // we just need to mint on received
    function onGmpReceived(
        bytes32,
        uint128,
        bytes32,
        bytes calldata b
    ) external payable returns (bytes32) {
        require(msg.sender == _gateway, "unauthorized");
        CrosschainMessage memory message = abi.decode(b, (CrosschainMessage));
        _safeMint(message.newHolder, message.tokenId);
        _burntBy[message.tokenId] = address(0);

        return bytes32("");
    }

    function encodeCrosschainMessage(
        uint256 _tokenId,
        address _newHolder
    ) public pure returns (bytes memory) {
        CrosschainMessage memory message = CrosschainMessage(
            _tokenId,
            _newHolder
        );
        return abi.encode(message);
    }

    function crosschainTransfer(
        uint256 _tokenId,
        address _newHolder,
        uint16 _destinationNetwork
    ) public {
        require(
            _crosschainContract[_destinationNetwork] != address(0),
            "Crosschain: Unsupport Network"
        );
        require(
            _ownerOf(_tokenId) == msg.sender,
            "Crosschain: Token is not owned by Sender"
        );
        burn(_tokenId);
        IGateway gateway = IGateway(_gateway);
        gateway.submitMessage(
            _crosschainContract[_destinationNetwork],
            _destinationNetwork,
            3000000,
            encodeCrosschainMessage(_tokenId, _newHolder)
        );
    }

    function currentDrop() public view returns (DropReturn memory) {
        Drop storage drop = DropList[_nextDropId];
        DropReturn memory dropReturn = DropReturn(
            drop.supply,
            drop.minted,
            drop.mintLimitPerWallet,
            drop.startTime,
            drop.endTime,
            drop.price,
            drop.hasWhiteListPhase,
            drop.whiteListEndTime,
            drop.whiteListPrice
        );
        return dropReturn;
    }

    function burn(uint256 _tokenId) public override {
        super.burn(_tokenId);
        _burntBy[_tokenId] = msg.sender;
    }

    function burntBy(uint256 _tokenId) public view returns (address) {
        return _burntBy[_tokenId];
    }

    function getWhiteListAccess(
        address _userAddress
    ) public view returns (bool) {
        Drop storage drop = DropList[_nextDropId];
        return drop.whiteListAddresses[_userAddress];
    }

    function getMintCount(address _userAddress) public view returns (uint256) {
        Drop storage drop = DropList[_nextDropId];
        return drop.mintedPerWallet[_userAddress];
    }

    function setBaseURI(
        string memory _baseURI
    ) public onlyOwner beforeUpload onlyAfterDrop {
        baseURI = _baseURI;
        _baseURISet = true;
    }

    function setLogoURI(string memory _logoURI) public onlyOwner {
        logoURI = _logoURI;
    }

    function safeMint(
        uint256 amount
    ) public payable onlyDuringDrop canMint(amount) {
        Drop storage drop = DropList[_nextDropId];
        uint256 pricePerToken = drop.price;
        if (
            drop.hasWhiteListPhase && block.timestamp <= drop.whiteListEndTime
        ) {
            require(
                drop.whiteListAddresses[msg.sender],
                "Only whitelist address can mint during whitelist phase."
            );
            pricePerToken = drop.whiteListPrice;
        }
        require(
            pricePerToken * amount == msg.value,
            "Please set the right value for minting"
        );

        payable(owner()).transfer(msg.value);

        for (uint256 i = 0; i < amount; i++) {
            uint256 tokenId = _nextTokenId++;
            _safeMint(msg.sender, tokenId);
        }
        drop.minted += amount;
        drop.mintedPerWallet[msg.sender] += amount;
    }

    function createDrop(
        uint256 _supply,
        uint256 _mintLimitPerWallet,
        uint256 _startTime,
        uint256 _endTime,
        uint256 _price,
        bool _hasWhiteListPhase,
        uint256 _whiteListEndTime,
        uint256 _whiteListPrice,
        address[] memory _whiteListAddresses
    ) external onlyOwner beforeUpload {
        Drop storage drop = DropList[_nextDropId];
        require(block.timestamp > drop.endTime, "Ongoing drop exists");

        _nextDropId++;

        Drop storage newDrop = DropList[_nextDropId];

        newDrop.supply = _supply;
        newDrop.minted = 0;
        newDrop.mintLimitPerWallet = _mintLimitPerWallet;
        newDrop.startTime = _startTime;
        newDrop.endTime = _endTime;
        newDrop.price = _price;
        newDrop.hasWhiteListPhase = _hasWhiteListPhase;
        newDrop.whiteListEndTime = _whiteListEndTime;
        newDrop.whiteListPrice = _whiteListPrice;

        for (uint256 i = 0; i < _whiteListAddresses.length; i++) {
            newDrop.whiteListAddresses[_whiteListAddresses[i]] = true;
        }
    }

    function tokenURI(
        uint256 tokenId
    ) public view override(ERC721, ERC721URIStorage) returns (string memory) {
        require(
            _ownerOf(tokenId) != address(0),
            "ERC721Metadata: URI query for nonexistent token"
        );

        require(_baseURISet, "Not revealed yet");

        return
            string(abi.encodePacked(baseURI, "/metadata/", tokenId.toString()));
    }

    function supportsInterface(
        bytes4 interfaceId
    ) public view override(ERC721, ERC721URIStorage) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

